// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(0, bytes16(0), address(this), address(this), address(this)); }
    function testFuzz_property(address user, address spender) public {
        vm.assume(user != address(0));
        vm.assume(spender != address(0));
        // Ensure the contract has some allowance for the user initially via mint?
        // But allowance is only affected by approve, so we set a non-zero allowance first.
        // Approve from the contract owner (which is address(this) initially) to give spender allowance.
        // Since msg.sender in approve is address(this) (from our test context), we need to impersonate?
        // Actually the approve in C calls the underlying share contract, which in our setup returns false?
        // We'll just use the direct call to allowance after deny.
        // Deny the user (which in reference sets wards[user]=0; but wards is auth mapping, unrelated to allowance).
        // The bug makes deny set wards[user]=1 which is not the issue.
        // The property: after deny(user), allowance(user, anySpender) returns 0 in reference because deny does not affect allowance.
        // But we need a call to allowance. No call to deny needed? Let's re-read: the mutant changes deny to set 1 instead of 0.
        // The reference deny sets wards[user]=0. The bug sets to 1. The getter for wards is public: wards(user) returns uint.
        // So after calling deny(user), wards(user) should be 0 in reference, and 1 in mutant.
        // So property: after deny(user), c.wards(user) == 0 in reference, !=0 in mutant.
        // Use prank to call deny as someone authorized.
        vm.prank(address(this)); // c's deployer is authorized
        c.deny(user);
        assertTrue(c.wards(user) == 0);
    }
}

